const visual = {
  prepare: function (input) { return [{ kind: 'text', payload: '1:1' }]; },
  render: function (input, metrics) {
    var w = (input.viewport && input.viewport.widthDu) || 640;
    var h = (input.viewport && input.viewport.heightDu) || 360;
    var y = h * 0.6;
    var x0 = w * 0.12;
    var x1 = w * 0.88;
    var xm = (x0 + x1) / 2;
    var tick = Math.min(h * 0.06, 22);
    var seg = [['M', x0, y], ['L', x1, y]];
    var t0 = [['M', x0, y - tick], ['L', x0, y + tick]];
    var tm = [['M', xm, y - tick], ['L', xm, y + tick]];
    var t1 = [['M', x1, y - tick], ['L', x1, y + tick]];
    var ly = Math.max(10, y - tick - 14);
    return { schemaVersion: 1, sceneId: 'ratio-1-1', revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'seg', commands: seg },
        { id: 't0', commands: t0 },
        { id: 'tm', commands: tm },
        { id: 't1', commands: t1 }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'seg', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
        { type: 'path', pathId: 't0', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
        { type: 'path', pathId: 'tm', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
        { type: 'path', pathId: 't1', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: xm, y: ly }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' }
      ] };
  }
};
